#include <stdio.h>
#include <string.h>

// Define colors
#define RED 0
#define YELLOW 1
#define BLUE 2
#define ORANGE 3
#define WHITE 4
#define GREEN 5

// Cube structure: 6 faces, each 2x2
// faces[0] = top (red), faces[1] = front (yellow), faces[2] = right (blue)
// faces[3] = bottom (orange), faces[4] = back (white), faces[5] = left (green)
int cube[6][2][2];

void init_cube() {
    // Initialize all faces with their colors
    for (int f = 0; f < 6; f++) {
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                cube[f][i][j] = f;
            }
        }
    }
}

// Rotate a face clockwise (90 degrees)
void rotate_face(int face) {
    int temp[2][2];
    // Copy face
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 2; j++)
            temp[i][j] = cube[face][i][j];
    // Rotate clockwise
    cube[face][0][0] = temp[1][0];
    cube[face][0][1] = temp[0][0];
    cube[face][1][0] = temp[1][1];
    cube[face][1][1] = temp[0][1];
}

// Get color as character
char color_char(int c) {
    switch(c) {
        case 0: return 'R';
        case 1: return 'Y';
        case 2: return 'B';
        case 3: return 'O';
        case 4: return 'W';
        case 5: return 'G';
        default: return '?';
    }
}

// Perform U move (top face clockwise)
void move_U() {
    // Rotate top face
    rotate_face(0);

    // Rotate adjacent edges: front->right->back->left
    // Save front top row
    int temp[2];
    temp[0] = cube[1][0][0];
    temp[1] = cube[1][0][1];

    // left -> front
    cube[1][0][0] = cube[5][0][0];
    cube[1][0][1] = cube[5][0][1];

    // back -> left
    cube[5][0][0] = cube[4][0][0];
    cube[5][0][1] = cube[4][0][1];

    // right -> back
    cube[4][0][0] = cube[2][0][0];
    cube[4][0][1] = cube[2][0][1];

    // front -> right
    cube[2][0][0] = temp[0];
    cube[2][0][1] = temp[1];
}

// Perform F move (front face clockwise)
void move_F() {
    // Rotate front face
    rotate_face(1);

    // Save top front row
    int temp[2];
    temp[0] = cube[0][1][0];
    temp[1] = cube[0][1][1];

    // left -> top (left column reversed)
    cube[0][1][0] = cube[5][1][1];
    cube[0][1][1] = cube[5][0][1];

    // bottom -> left (bottom row reversed)
    cube[5][0][1] = cube[3][0][0];
    cube[5][1][1] = cube[3][0][1];

    // right -> bottom (right column)
    cube[3][0][0] = cube[2][0][0];
    cube[3][0][1] = cube[2][1][0];

    // top -> right
    cube[2][0][0] = temp[0];
    cube[2][1][0] = temp[1];
}

// Perform R move (right face clockwise)
void move_R() {
    // Rotate right face
    rotate_face(2);

    // Save top right column
    int temp[2];
    temp[0] = cube[0][0][1];
    temp[1] = cube[0][1][1];

    // front -> top
    cube[0][0][1] = cube[1][0][1];
    cube[0][1][1] = cube[1][1][1];

    // bottom -> front
    cube[1][0][1] = cube[3][0][1];
    cube[1][1][1] = cube[3][1][1];

    // back -> bottom (reversed)
    cube[3][0][1] = cube[4][1][1];
    cube[3][1][1] = cube[4][0][1];

    // top -> back
    cube[4][0][1] = temp[1];
    cube[4][1][1] = temp[0];
}

// Perform D move (bottom face clockwise)
void move_D() {
    // Rotate bottom face
    rotate_face(3);

    // Save front bottom row
    int temp[2];
    temp[0] = cube[1][1][0];
    temp[1] = cube[1][1][1];

    // right -> front
    cube[1][1][0] = cube[2][1][0];
    cube[1][1][1] = cube[2][1][1];

    // back -> right
    cube[2][1][0] = cube[4][1][0];
    cube[2][1][1] = cube[4][1][1];

    // left -> back
    cube[4][1][0] = cube[5][1][0];
    cube[4][1][1] = cube[5][1][1];

    // front -> left
    cube[5][1][0] = temp[0];
    cube[5][1][1] = temp[1];
}

// Perform B move (back face clockwise)
void move_B() {
    // Rotate back face
    rotate_face(4);

    // Save top back row
    int temp[2];
    temp[0] = cube[0][0][0];
    temp[1] = cube[0][0][1];

    // right -> top
    cube[0][0][0] = cube[2][1][1];
    cube[0][0][1] = cube[2][0][1];

    // bottom -> right
    cube[2][0][1] = cube[3][1][1];
    cube[2][1][1] = cube[3][1][0];

    // left -> bottom
    cube[3][1][0] = cube[5][0][0];
    cube[3][1][1] = cube[5][1][0];

    // top -> left
    cube[5][0][0] = temp[1];
    cube[5][1][0] = temp[0];
}

// Perform L move (left face clockwise)
void move_L() {
    // Rotate left face
    rotate_face(5);

    // Save top left column
    int temp[2];
    temp[0] = cube[0][0][0];
    temp[1] = cube[0][1][0];

    // back -> top
    cube[0][0][0] = cube[4][1][0];
    cube[0][1][0] = cube[4][0][0];

    // bottom -> back
    cube[4][0][0] = cube[3][1][0];
    cube[4][1][0] = cube[3][0][0];

    // front -> bottom
    cube[3][0][0] = cube[1][0][0];
    cube[3][1][0] = cube[1][1][0];

    // top -> front
    cube[1][0][0] = temp[0];
    cube[1][1][0] = temp[1];
}

