#include <iostream>
#include <string>
#include <vector>
using namespace std;

// Define the 6 faces: U(0), F(1), R(2), D(3), B(4), L(5)
// Each face is a 2x2 grid, stored as a 4-element array:
// [0][1]
// [2][3]
// We'll use a vector of 6 vectors, each of size 4.
vector<vector<char>> cube(6, vector<char>(4));

// Initialize cube to solved state
void initCube() {
    // U: red
    for (int i = 0; i < 4; i++) cube[0][i] = 'r';
    // F: yellow
    for (int i = 0; i < 4; i++) cube[1][i] = 'y';
    // R: blue
    for (int i = 0; i < 4; i++) cube[2][i] = 'b';
    // D: orange
    for (int i = 0; i < 4; i++) cube[3][i] = 'o';
    // B: white
    for (int i = 0; i < 4; i++) cube[4][i] = 'w';
    // L: green
    for (int i = 0; i < 4; i++) cube[5][i] = 'g';
}

// Rotate a face clockwise (90 degrees)
// indices: 0 1 -> 2 0
//          2 3 -> 3 1
void rotateFace(int face) {
    vector<char> old = cube[face];
    cube[face][0] = old[2];
    cube[face][1] = old[0];
    cube[face][2] = old[3];
    cube[face][3] = old[1];
}

// Apply a move U, F, R, D, B, L (clockwise)
void applyMove(char move) {
    switch (move) {
        case 'U': {
            rotateFace(0);
            // Adjacent pieces: F top row, L top row, B top row, R top row
            // Save F top row (indices 0,1)
            char f0 = cube[1][0], f1 = cube[1][1];
            // L top row -> F top row
            cube[1][0] = cube[5][0]; cube[1][1] = cube[5][1];
            // B top row -> L top row (B is reversed: index 1 then 0)
            cube[5][0] = cube[4][1]; cube[5][1] = cube[4][0];
            // R top row -> B top row (R is reversed: index 1 then 0)
            cube[4][0] = cube[2][1]; cube[4][1] = cube[2][0];
            // saved F -> R top row
            cube[2][0] = f0; cube[2][1] = f1;
            break;
        }
        case 'F': {
            rotateFace(1);
            // Adjacent: U bottom row (indices 2,3), R left column (0,2), D top row (0,1), L right column (1,3)
            // Save U bottom row
            char u2 = cube[0][2], u3 = cube[0][3];
            // L right column (1,3) -> U bottom row (but reversed: 3 then 1)
            cube[0][2] = cube[5][3]; cube[0][3] = cube[5][1];
            // D top row -> L right column (reversed: 1 then 0)
            cube[5][1] = cube[3][0]; cube[5][3] = cube[3][1];
            // R left column -> D top row
            cube[3][0] = cube[2][0]; cube[3][1] = cube[2][2];
            // saved U -> R left column
            cube[2][0] = u2; cube[2][2] = u3;
            break;
        }
        case 'R': {
            rotateFace(2);
            // Adjacent: U right column (1,3), B left column (0,2) reversed, D right column (1,3) reversed, F right column (1,3)
            // Save U right column
            char u1 = cube[0][1], u3 = cube[0][3];
            // F right column -> U right column
            cube[0][1] = cube[1][1]; cube[0][3] = cube[1][3];
            // D right column (reversed) -> F right column
            cube[1][1] = cube[3][3]; cube[1][3] = cube[3][1];
            // B left column (reversed) -> D right column
            cube[3][1] = cube[4][2]; cube[3][3] = cube[4][0];
            // saved U -> B left column
            cube[4][0] = u3; cube[4][2] = u1;
            break;
        }
        case 'D': {
            rotateFace(3);
            // Adjacent: F bottom row (2,3), R bottom row (2,3), B bottom row (2,3), L bottom row (2,3)
            // Save F bottom row
            char f2 = cube[1][2], f3 = cube[1][3];
            // R bottom row -> F bottom row
            cube[1][2] = cube[2][2]; cube[1][3] = cube[2][3];
            // B bottom row (reversed) -> R bottom row
            cube[2][2] = cube[4][3]; cube[2][3] = cube[4][2];
            // L bottom row (reversed) -> B bottom row
            cube[4][2] = cube[5][3]; cube[4][3] = cube[5][2];
            // saved F -> L bottom row
            cube[5][2] = f2; cube[5][3] = f3;
            break;
        }
        case 'B': {
            rotateFace(4);
            // Adjacent: U top row (0,1) reversed, L left column (0,2), D bottom row (2,3) reversed, R right column (1,3)
            // Save U top row
            char u0 = cube[0][0], u1 = cube[0][1];
            // R right column -> U top row (reversed)
            cube[0][0] = cube[2][3]; cube[0][1] = cube[2][1];
            // D bottom row (reversed) -> R right column
            cube[2][1] = cube[3][3]; cube[2][3] = cube[3][2];
            // L left column -> D bottom row (reversed)
            cube[3][2] = cube[5][0]; cube[3][3] = cube[5][2];
            // saved U -> L left column
            cube[5][0] = u1; cube[5][2] = u0;
            break;
        }
        case 'L': {
            rotateFace(5);
            // Adjacent: U left column (0,2), F left column (0,2), D left column (0,2), B right column (1,3) reversed
            // Save U left column
            char u0 = cube[0][0], u2 = cube[0][2];
            // B right column (reversed) -> U left column
            cube[0][0] = cube[4][3]; cube[0][2] = cube[4][1];
            // D left column -> B right column (reversed)
            cube[4][1] = cube[3][0]; cube[4][3] = cube[3][2];
            // F left column -> D left column
            cube[3][0] = cube[1][0]; cube[3][2] = cube[1][2];
            // saved U -> F left column
            cube[1][0] = u0; cube[1][2] = u2;
            break;
        }
    }
}

// Print the net diagram as specified
void printNet() {
    // Line 1: "   " + U row0
    cout << "   " << cube[0][0] << cube[0][1] << endl;
    // Line 2: "   " + U row1
    cout << "   " << cube[0][2] << cube[0][3] << endl;
    // Line 3: L row0 + F row0 + R row0 + B row0
    cout << cube[5][0] << cube[5][1] << cube[1][0] << cube[1][1] << cube[2][0] << cube[2][1] << cube[4][0] << cube[4][1] << endl;
    // Line 4: L row1 + F row1 + R row1 + B row1
    cout << cube[5][2] << cube[5][3] << cube[1][2] << cube[1][3] << cube[2][2] << cube[2][3] << cube[4][2] << cube[4][3] << endl;
    // Line 5: "   " + D row0
    cout << "   " << cube[3][0] << cube[3][1] << endl;
    // Line 6: "   " + D row1
    cout << "   " << cube[3][2] << cube[3][3] << endl;
}

int main() {
    initCube();
    string S;
    getline(cin, S);
    for (char c : S) {
        if (c == 'U' || c == 'F' || c == 'R' || c == 'D' || c == 'B' || c == 'L') {
            applyMove(c);
        }
    }
    printNet();
    return 0;
}

