// 24 stickers: U0,U1,U2,U3, F0,F1,F2,F3, R0,R1,R2,R3, D0,D1,D2,D3, B0,B1,B2,B3, L0,L1,L2,L3
// Face viewed from outside: [0]=TL,[1]=TR,[2]=BL,[3]=BR

int state[24];
// Colors: 0=red(U), 1=yellow(F), 2=blue(R), 3=orange(D), 4=white(B), 5=green(L)

void applyPerm(vector<vector<int>>& cycles) {
    for (auto& c : cycles) {
        int tmp = state[c.back()];
        for (int i = c.size()-1; i > 0; i--) state[c[i]] = state[c[i-1]];
        state[c[0]] = tmp;
    }
}

#include <bits/stdc++.h>
using namespace std;

struct Sticker {
    int x, y, z;   // position: each in {-1, 1}
    int nx, ny, nz; // outward normal: one of the 6 axis directions
    char color;
};

static inline void rotXcw(int &y, int &z) { // clockwise when viewed from +X
    int ny = -z, nz = y;
    y = ny; z = nz;
}
static inline void rotYcw(int &x, int &z) { // clockwise when viewed from +Y
    int nx = z, nz = -x;
    x = nx; z = nz;
}
static inline void rotZcw(int &x, int &y) { // clockwise when viewed from +Z
    int nx = y, ny = -x;
    x = nx; y = ny;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    cin >> S;

    vector<Sticker> st;

    // Initial solved cube:
    // U(+Y)=R, D(-Y)=O, F(+Z)=Y, B(-Z)=W, R(+X)=B, L(-X)=G
    // Each face has 4 stickers at the four corresponding corner positions.

    // U face
    for (int x : {-1, 1}) for (int z : {-1, 1})
        st.push_back({x, 1, z, 0, 1, 0, 'R'});
    // D face
    for (int x : {-1, 1}) for (int z : {-1, 1})
        st.push_back({x, -1, z, 0, -1, 0, 'O'});
    // F face
    for (int x : {-1, 1}) for (int y : {-1, 1})
        st.push_back({x, y, 1, 0, 0, 1, 'Y'});
    // B face
    for (int x : {-1, 1}) for (int y : {-1, 1})
        st.push_back({x, y, -1, 0, 0, -1, 'W'});
    // R face
    for (int y : {-1, 1}) for (int z : {-1, 1})
        st.push_back({1, y, z, 1, 0, 0, 'B'});
    // L face
    for (int y : {-1, 1}) for (int z : {-1, 1})
        st.push_back({-1, y, z, -1, 0, 0, 'G'});

    for (char c : S) {
        for (auto &s : st) {
            if (c == 'U' && s.y == 1) {
                rotYcw(s.x, s.z);
                rotYcw(s.nx, s.nz);
            } else if (c == 'D' && s.y == -1) {
                // clockwise when viewed from -Y == ccw around +Y
                for (int k = 0; k < 3; k++) {
                    rotYcw(s.x, s.z);
                    rotYcw(s.nx, s.nz);
                }
            } else if (c == 'R' && s.x == 1) {
                rotXcw(s.y, s.z);
                rotXcw(s.ny, s.nz);
            } else if (c == 'L' && s.x == -1) {
                // clockwise when viewed from -X == ccw around +X
                for (int k = 0; k < 3; k++) {
                    rotXcw(s.y, s.z);
                    rotXcw(s.ny, s.nz);
                }
            } else if (c == 'F' && s.z == 1) {
                rotZcw(s.x, s.y);
                rotZcw(s.nx, s.ny);
            } else if (c == 'B' && s.z == -1) {
                // clockwise when viewed from -Z == ccw around +Z
                for (int k = 0; k < 3; k++) {
                    rotZcw(s.x, s.y);
                    rotZcw(s.nx, s.ny);
                }
            }
        }
    }

    // face[face_id][row][col]
    // net:
    //   U
    // L F R B
    //   D
    vector<string> U(2, "??"), L(2, "??"), F(2, "??"), R(2, "??"), B(2, "??"), D(2, "??");

    for (auto &s : st) {
        if (s.nx == 0 && s.ny == 1 && s.nz == 0) { // U
            int row = (s.z == -1 ? 0 : 1);
            int col = (s.x == -1 ? 0 : 1);
            U[row][col] = s.color;
        } else if (s.nx == 0 && s.ny == -1 && s.nz == 0) { // D
            int row = (s.z == 1 ? 0 : 1);
            int col = (s.x == -1 ? 0 : 1);
            D[row][col] = s.color;
        } else if (s.nx == 0 && s.ny == 0 && s.nz == 1) { // F
            int row = (s.y == 1 ? 0 : 1);
            int col = (s.x == -1 ? 0 : 1);
            F[row][col] = s.color;
        } else if (s.nx == 0 && s.ny == 0 && s.nz == -1) { // B
            int row = (s.y == 1 ? 0 : 1);
            int col = (s.x == 1 ? 0 : 1); // mirrored to match unfolded net
            B[row][col] = s.color;
        } else if (s.nx == 1 && s.ny == 0 && s.nz == 0) { // R
            int row = (s.y == 1 ? 0 : 1);
            int col = (s.z == 1 ? 0 : 1); // left-to-right: front to back
            R[row][col] = s.color;
        } else if (s.nx == -1 && s.ny == 0 && s.nz == 0) { // L
            int row = (s.y == 1 ? 0 : 1);
            int col = (s.z == -1 ? 0 : 1); // left-to-right: back to front
            L[row][col] = s.color;
        }
    }

    cout << "  " << U[0] << "\n";
    cout << "  " << U[1] << "\n";
    cout << L[0] << F[0] << R[0] << B[0] << "\n";
    cout << L[1] << F[1] << R[1] << B[1] << "\n";
    cout << "  " << D[0] << "\n";
    cout << "  " << D[1] << "\n";

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {

    // colors: 0=Red, 1=Yellow, 2=Blue, 3=Orange, 4=White, 5=Green
    // faces order: U, D, F, B, R, L
    // each face has 4 cells (2x2), stored as 2x2 array

    static int[][][] cube = new int[6][2][2];

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        initCube();

        for (int i = 0; i < s.length(); i++) {
            char move = s.charAt(i);
            switch (move) {
                case 'U': rotateU(); break;
                case 'D': rotateD(); break;
                case 'F': rotateF(); break;
                case 'B': rotateB(); break;
                case 'R': rotateR(); break;
                case 'L': rotateL(); break;
            }
        }

        printCube();
    }

    static void initCube() {
        // U (top) = Red (0)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                cube[0][i][j] = 0;
        // D (bottom) = Orange (3)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                cube[1][i][j] = 3;
        // F (front) = Yellow (1)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                cube[2][i][j] = 1;
        // B (back) = White (4)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                cube[3][i][j] = 4;
        // R (right) = Blue (2)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                cube[4][i][j] = 2;
        // L (left) = Green (5)
        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++)
                cube[5][i][j] = 5;
    }

    // rotate a face clockwise (90 deg)
    static int[][] rotateFace(int[][] face) {
        int[][] res = new int[2][2];
        res[0][0] = face[1][0];
        res[0][1] = face[0][0];
        res[1][0] = face[1][1];
        res[1][1] = face[0][1];
        return res;
    }

    // U move
    static void rotateU() {
        cube[0] = rotateFace(cube[0]);
        // save top row of F, R, B, L
        int[] save = new int[2];
        for (int i = 0; i < 2; i++) save[i] = cube[2][0][i]; // F top row
        for (int i = 0; i < 2; i++) cube[2][0][i] = cube[5][0][i]; // L -> F
        for (int i = 0; i < 2; i++) cube[5][0][i] = cube[3][0][i]; // B -> L
        for (int i = 0; i < 2; i++) cube[3][0][i] = cube[4][0][i]; // R -> B
        for (int i = 0; i < 2; i++) cube[4][0][i] = save[i]; // save -> R
    }

    // D move
    static void rotateD() {
        cube[1] = rotateFace(cube[1]);
        int[] save = new int[2];
        for (int i = 0; i < 2; i++) save[i] = cube[2][1][i]; // F bottom row
        for (int i = 0; i < 2; i++) cube[2][1][i] = cube[4][1][i]; // R -> F
        for (int i = 0; i < 2; i++) cube[4][1][i] = cube[3][1][i]; // B -> R
        for (int i = 0; i < 2; i++) cube[3][1][i] = cube[5][1][i]; // L -> B
        for (int i = 0; i < 2; i++) cube[5][1][i] = save[i]; // save -> L
    }

    // F move
    static void rotateF() {
        cube[2] = rotateFace(cube[2]);
        int[] save = new int[2];
        // save right column of U
        for (int i = 0; i < 2; i++) save[i] = cube[0][i][1];
        // L right column -> U right column (but reversed order)
        for (int i = 0; i < 2; i++) cube[0][i][1] = cube[5][1-i][1];
        // D top row (index 0) -> L right column
        for (int i = 0; i < 2; i++) cube[5][i][1] = cube[1][0][i];
        // R left column -> D top row (reversed)
        for (int i = 0; i < 2; i++) cube[1][0][i] = cube[4][1-i][0];
        // save -> R left column
        for (int i = 0; i < 2; i++) cube[4][i][0] = save[i];
    }

    // B move
    static void rotateB() {
        cube[3] = rotateFace(cube[3]);
        int[] save = new int[2];
        // save left column of U
        for (int i = 0; i < 2; i++) save[i] = cube[0][i][0];
        // R right column -> U left column (reversed)
        for (int i = 0; i < 2; i++) cube[0][i][0] = cube[4][1-i][1];
        // D bottom row (index 1) -> R right column
        for (int i = 0; i < 2; i++) cube[4][i][1] = cube[1][1][i];
        // L left column -> D bottom row (reversed)
        for (int i = 0; i < 2; i++) cube[1][1][i] = cube[5][1-i][0];
        // save -> L left column
        for (int i = 0; i < 2; i++) cube[5][i][0] = save[i];
    }

    // R move
    static void rotateR() {
        cube[4] = rotateFace(cube[4]);
        int[] save = new int[2];
        // save right column of U
        for (int i = 0; i < 2; i++) save[i] = cube[0][i][1];
        // F right column -> U right column
        for (int i = 0; i < 2; i++) cube[0][i][1] = cube[2][i][1];
        // D right column -> F right column (reversed)
        for (int i = 0; i < 2; i++) cube[2][i][1] = cube[1][1-i][1];
        // B left column -> D right column (reversed)
        for (int i = 0; i < 2; i++) cube[1][i][1] = cube[3][1-i][0];
        // save -> B left column
        for (int i = 0; i < 2; i++) cube[3][i][0] = save[i];
    }

    // L move
    static void rotateL() {
        cube[5] = rotateFace(cube[5]);
        int[] save = new int[2];
        // save left column of U
        for (int i = 0; i < 2; i++) save[i] = cube[0][i][0];
        // B right column -> U left column
        for (int i = 0; i < 2; i++) cube[0][i][0] = cube[3][1-i][1];
        // D left column -> B right column (reversed)
        for (int i = 0; i < 2; i++) cube[3][i][1] = cube[1][1-i][0];
        // F left column -> D left column
        for (int i = 0; i < 2; i++) cube[1][i][0] = cube[2][i][0];
        // save -> F left column
        for (int i = 0; i < 2; i++) cube[2][i][0] = save[i];
    }

    static String colorChar(int c) {
        switch (c) {
            case 0: return "r";
            case 1: return "y";
            case 2: return "b";
            case 3: return "o";
            case 4: return "w";
            case 5: return "g";
            default: return "?";
        }
    }

    static void printCube() {
        // Development diagram layout:
        //       U
        //   L   F   R   B
        //       D
        // Each face is 2x2

        // Print top face (U)
        for (int i = 0; i < 2; i++) {
            System.out.print("  ");
            for (int j = 0; j < 2; j++) {
                System.out.print(colorChar(cube[0][i][j]));
            }
            System.out.println();
        }

        // Print middle row: L, F, R, B
        for (int i = 0; i < 2; i++) {
            // L
            for (int j = 0; j < 2; j++) {
                System.out.print(colorChar(cube[5][i][j]));
            }
            System.out.print(" ");
            // F
            for (int j = 0; j < 2; j++) {
                System.out.print(colorChar(cube[2][i][j]));
            }
            System.out.print(" ");
            // R
            for (int j = 0; j < 2; j++) {
                System.out.print(colorChar(cube[4][i][j]));
            }
            System.out.print(" ");
            // B
            for (int j = 0; j < 2; j++) {
                System.out.print(colorChar(cube[3][i][j]));
            }
            System.out.println();
        }

        // Print bottom face (D)
        for (int i = 0; i < 2; i++) {
            System.out.print("  ");
            for (int j = 0; j < 2; j++) {
                System.out.print(colorChar(cube[1][i][j]));
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Face order: U, F, R, D, B, L
    // Colors in initial state:
    // U=Red, F=Yellow, R=Blue, D=Orange, B=White, L=Green

    static class Cubie {
        char[] c = new char[6]; // sticker color on each global direction face, '.' if none

        Cubie() {
            Arrays.fill(c, '.');
        }

        Cubie copy() {
            Cubie x = new Cubie();
            System.arraycopy(this.c, 0, x.c, 0, 6);
            return x;
        }
    }

    static Cubie[][][] cube = new Cubie[2][2][2];

    static final int U = 0, F = 1, R = 2, D = 3, B = 4, L = 5;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) s = "";
        s = s.trim();

        initCube();

        for (char ch : s.toCharArray()) {
            rotate(ch);
        }

        StringBuilder out = new StringBuilder();

        // Development diagram:
        //   U
        // L F R B
        //   D
        //
        // Each face is 2x2.

        String[] u = getFace(U);
        String[] l = getFace(L);
        String[] f = getFace(F);
        String[] r = getFace(R);
        String[] b = getFace(B);
        String[] d = getFace(D);

        out.append("  ").append(u[0]).append('\n');
        out.append("  ").append(u[1]).append('\n');
        out.append(l[0]).append(f[0]).append(r[0]).append(b[0]).append('\n');
        out.append(l[1]).append(f[1]).append(r[1]).append(b[1]).append('\n');
        out.append("  ").append(d[0]).append('\n');
        out.append("  ").append(d[1]).append('\n');

        System.out.print(out.toString());
    }

    static void initCube() {
        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                for (int z = 0; z < 2; z++) {
                    cube[x][y][z] = new Cubie();
                    if (y == 1) cube[x][y][z].c[U] = 'r';
                    if (y == 0) cube[x][y][z].c[D] = 'o';
                    if (z == 1) cube[x][y][z].c[F] = 'y';
                    if (z == 0) cube[x][y][z].c[B] = 'w';
                    if (x == 1) cube[x][y][z].c[R] = 'b';
                    if (x == 0) cube[x][y][z].c[L] = 'g';
                }
            }
        }
    }

    static void rotate(char op) {
        switch (op) {
            case 'U': rotateLayerY(1, true); break;
            case 'D': rotateLayerY(0, false); break;
            case 'F': rotateLayerZ(1, true); break;
            case 'B': rotateLayerZ(0, false); break;
            case 'R': rotateLayerX(1, true); break;
            case 'L': rotateLayerX(0, false); break;
        }
    }

    // Clockwise when viewed from +Y side
    static void rotateLayerY(int layer, boolean clockwise) {
        Cubie[][] old = new Cubie[2][2];
        for (int x = 0; x < 2; x++) for (int z = 0; z < 2; z++) old[x][z] = cube[x][layer][z].copy();

        for (int x = 0; x < 2; x++) {
            for (int z = 0; z < 2; z++) {
                int nx, nz;
                if (clockwise) {
                    nx = z;
                    nz = 1 - x;
                } else {
                    nx = 1 - z;
                    nz = x;
                }
                cube[nx][layer][nz] = rotateCubieAroundY(old[x][z], clockwise);
            }
        }
    }

    // Clockwise when viewed from +Z side
    static void rotateLayerZ(int layer, boolean clockwise) {
        Cubie[][] old = new Cubie[2][2];
        for (int x = 0; x < 2; x++) for (int y = 0; y < 2; y++) old[x][y] = cube[x][y][layer].copy();

        for (int x = 0; x < 2; x++) {
            for (int y = 0; y < 2; y++) {
                int nx, ny;
                if (clockwise) {
                    nx = y;
                    ny = 1 - x;
                } else {
                    nx = 1 - y;
                    ny = x;
                }
                cube[nx][ny][layer] = rotateCubieAroundZ(old[x][y], clockwise);
            }
        }
    }

    // Clockwise when viewed from +X side
    static void rotateLayerX(int layer, boolean clockwise) {
        Cubie[][] old = new Cubie[2][2];
        for (int y = 0; y < 2; y++) for (int z = 0; z < 2; z++) old[y][z] = cube[layer][y][z].copy();

        for (int y = 0; y < 2; y++) {
            for (int z = 0; z < 2; z++) {
                int ny, nz;
                if (clockwise) {
                    ny = z;
                    nz = 1 - y;
                } else {
                    ny = 1 - z;
                    nz = y;
                }
                cube[layer][ny][nz] = rotateCubieAroundX(old[y][z], clockwise);
            }
        }
    }

    static Cubie rotateCubieAroundY(Cubie a, boolean clockwise) {
        Cubie b = new Cubie();
        b.c[U] = a.c[U];
        b.c[D] = a.c[D];
        if (clockwise) {
            b.c[R] = a.c[F];
            b.c[B] = a.c[R];
            b.c[L] = a.c[B];
            b.c[F] = a.c[L];
        } else {
            b.c[L] = a.c[F];
            b.c[B] = a.c[L];
            b.c[R] = a.c[B];
            b.c[F] = a.c[R];
        }
        return b;
    }

    static Cubie rotateCubieAroundZ(Cubie a, boolean clockwise) {
        Cubie b = new Cubie();
        b.c[F] = a.c[F];
        b.c[B] = a.c[B];
        if (clockwise) {
            b.c[R] = a.c[U];
            b.c[D] = a.c[R];
            b.c[L] = a.c[D];
            b.c[U] = a.c[L];
        } else {
            b.c[L] = a.c[U];
            b.c[D] = a.c[L];
            b.c[R] = a.c[D];
            b.c[U] = a.c[R];
        }
        return b;
    }

    static Cubie rotateCubieAroundX(Cubie a, boolean clockwise) {
        Cubie b = new Cubie();
        b.c[R] = a.c[R];
        b.c[L] = a.c[L];
        if (clockwise) {
            b.c[B] = a.c[U];
            b.c[D] = a.c[B];
            b.c[F] = a.c[D];
            b.c[U] = a.c[F];
        } else {
            b.c[F] = a.c[U];
            b.c[D] = a.c[F];
            b.c[B] = a.c[D];
            b.c[U] = a.c[B];
        }
        return b;
    }

    static String[] getFace(int face) {
        String[] res = new String[2];
        StringBuilder row0 = new StringBuilder();
        StringBuilder row1 = new StringBuilder();

        switch (face) {
            case U:
                // viewed from top: rows back->front, cols left->right
                row0.append(cube[0][1][0].c[U]).append(cube[1][1][0].c[U]);
                row1.append(cube[0][1][1].c[U]).append(cube[1][1][1].c[U]);
                break;
            case D:
                // viewed from bottom: rows front->back, cols left->right
                row0.append(cube[0][0][1].c[D]).append(cube[1][0][1].c[D]);
                row1.append(cube[0][0][0].c[D]).append(cube[1][0][0].c[D]);
                break;
            case F:
                // viewed from front: rows top->bottom, cols left->right
                row0.append(cube[0][1][1].c[F]).append(cube[1][1][1].c[F]);
                row1.append(cube[0][0][1].c[F]).append(cube[1][0][1].c[F]);
                break;
            case B:
                // viewed from back: rows top->bottom, cols right->left
                row0.append(cube[1][1][0].c[B]).append(cube[0][1][0].c[B]);
                row1.append(cube[1][0][0].c[B]).append(cube[0][0][0].c[B]);
                break;
            case R:
                // viewed from right: rows top->bottom, cols front->back
                row0.append(cube[1][1][1].c[R]).append(cube[1][1][0].c[R]);
                row1.append(cube[1][0][1].c[R]).append(cube[1][0][0].c[R]);
                break;
            case L:
                // viewed from left: rows top->bottom, cols back->front
                row0.append(cube[0][1][0].c[L]).append(cube[0][1][1].c[L]);
                row1.append(cube[0][0][0].c[L]).append(cube[0][0][1].c[L]);
                break;
        }

        res[0] = row0.toString();
        res[1] = row1.toString();
        return res;
    }
}
